/* Timetable tab: renders window.TIMETABLE_DATA (generated by tools/analyze_timetable.py). */
(function () {
  var SUBJECTS = [
    { key: "reasoning", name: "Reasoning", code: "REA", color: "#6366f1" },
    { key: "quant", name: "Quantitative Aptitude", code: "QA", color: "#0ea5e9" },
    { key: "english", name: "English", code: "ENG", color: "#10b981" },
    { key: "ga", name: "General Awareness", code: "GA", color: "#f59e0b" }
  ];
  var GROUPS = [
    { key: "2025", label: "2025 Exam Batch" },
    { key: "2026", label: "2026 Exam Batch" }
  ];
  var state = { group: "2026" };

  function esc(value) {
    return String(value == null ? "" : value).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }

  function clock(minutes) {
    var total = 10 * 60 + minutes;
    var h = Math.floor(total / 60) % 24;
    var m = total % 60;
    return (h < 10 ? "0" : "") + h + ":" + (m < 10 ? "0" : "") + m;
  }

  function hours(minutes) {
    var h = Math.floor(minutes / 60);
    var m = minutes % 60;
    return h + "h" + (m ? " " + m + "m" : "");
  }

  function dateLabel(iso) {
    if (!iso) return "";
    var d = new Date(iso + "T00:00:00");
    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return d.getDate() + " " + months[d.getMonth()] + " " + d.getFullYear();
  }

  function dayCell(day, subject) {
    var blocks = day.sessions.filter(function (s) { return s.kind === "study" && s.subject === subject.key; });
    if (!blocks.length) return '<td class="zztt-cell zztt-off">—</td>';
    var total = blocks.reduce(function (sum, s) { return sum + s.duration; }, 0);
    var times = blocks.map(function (s) { return clock(s.start) + "–" + clock(s.end); }).join("<br>");
    return (
      '<td class="zztt-cell" style="border-top:3px solid ' + subject.color + '">' +
      '<div class="zztt-times">' + times + '</div>' +
      '<div class="zztt-total">' + hours(total) + "</div></td>"
    );
  }

  function buildHTML(group) {
    var data = window.TIMETABLE_DATA;
    if (!data || !data.days) {
      return '<div class="zztt-empty">timetable-data.js is missing. Run <code>python tools/analyze_timetable.py</code>.</div>';
    }
    var coverage = (data.coverage && data.coverage[group]) || {};
    var assignments = (data.assignments && data.assignments[group]) || {};
    var weekly = data.weeklyTotals || {};

    var chips = GROUPS.map(function (g) {
      return '<button class="zztt-chip" data-group="' + g.key + '"' + (g.key === group ? " data-active=\"1\"" : "") + ">" + g.label + "</button>";
    }).join("");

    var head =
      '<div class="zztt-head">' +
      '<div><div class="zztt-title">🗓️ 7-Day Study Timetable</div>' +
      '<div class="zztt-sub">All 7 days × 4 subjects · derived automatically from the coded schedule (' + esc(data.source) + ")</div></div>" +
      '<div class="zztt-head-right"><div class="zztt-chips">' + chips + "</div>" +
      '<button class="zztt-close" id="zztt-close" aria-label="Close">✕</button></div></div>';

    var cols = data.days.map(function (d) {
      return '<th><span class="zztt-day">' + esc(d.day) + '</span><span class="zztt-date">' + esc(dateLabel(d.dates && d.dates[group])) + "</span></th>";
    }).join("");

    var body = SUBJECTS.map(function (subject) {
      var cells = data.days.map(function (day) { return dayCell(day, subject); }).join("");
      var cov = coverage[subject.key] || {};
      return (
        '<tr><th class="zztt-rowhead"><span class="zztt-dot" style="background:' + subject.color + '"></span>' +
        '<span><strong>' + esc(subject.name) + "</strong><em>" + esc(subject.code) +
        " · " + (cov.weeklyHours || 0) + "h / week · " + (cov.daysCovered || 0) + "/7 days</em></span></th>" +
        cells + "</tr>"
      );
    }).join("");

    var footRow = "<tr><th class=\"zztt-rowhead zztt-foothead\">Daily load</th>" + data.days.map(function (day) {
      return '<td class="zztt-foot">' + hours(day.studyMinutes) + ' study<br><span>' + hours(day.breakMinutes) + " break</span></td>";
    }).join("") + "</tr>";

    var rankCols = data.days.map(function (d) { return "<th>" + esc(d.day) + "</th>"; }).join("");
    var rankRows = SUBJECTS.map(function (subject) {
      var map = assignments[subject.key] || {};
      var cells = data.days.map(function (d) {
        var rank = map[d.day];
        if (!rank) return '<td class="zztt-rank zztt-off">—</td>';
        return '<td class="zztt-rank' + (rank === 1 ? " zztt-best" : "") + '">' + (rank === 1 ? "★ 1" : rank) + "</td>";
      }).join("");
      return "<tr><th>" + esc(subject.code) + "</th>" + cells + "</tr>";
    }).join("");

    var totals = SUBJECTS.map(function (subject) {
      return '<span class="zztt-pill" style="border-color:' + subject.color + '">' + esc(subject.code) + " · " + hours(weekly[subject.key] || 0) + "</span>";
    }).join("");

    var note = (data.problems && data.problems.length)
      ? '<div class="zztt-warn">Parser checks: ' + esc(data.problems.join("; ")) + "</div>"
      : '<div class="zztt-ok">Parser checks: all 4 subjects scheduled, no unreadable slots.</div>';

    return (
      head +
      '<div class="zztt-totals">' + totals + "</div>" +
      '<div class="zztt-scroll"><table class="zztt-table"><thead><tr><th class="zztt-rowhead">Subject</th>' + cols + "</tr></thead><tbody>" + body + footRow + "</tbody></table></div>" +
      '<div class="zztt-section">Priority day per subject <span>(1 = the day with the most time; ★ marks the top pick)</span></div>' +
      '<div class="zztt-scroll"><table class="zztt-table zztt-compact"><thead><tr><th class="zztt-rowhead">Subject</th>' + rankCols + "</tr></thead><tbody>" + rankRows + "</tbody></table></div>" +
      note +
      '<div class="zztt-note">Both exam batches share this grid; switch the batch chip to see that batch’s calendar dates. Generated ' + esc(data.generatedAt || "") + ".</div>"
    );
  }

  function injectStyle() {
    if (document.getElementById("zztt-style")) return;
    var css = [
      "#zztt-overlay{position:fixed;inset:0;z-index:9999;background:rgba(15,23,42,.55);backdrop-filter:blur(3px);display:none;overflow:auto;padding:28px 18px}",
      "#zztt-overlay[data-open='1']{display:block}",
      ".zztt-panel{max-width:1240px;margin:0 auto;background:var(--panel,#fff);color:var(--text,#111827);border-radius:16px;box-shadow:0 24px 60px rgba(2,6,23,.35);padding:20px 22px 18px;border:1px solid rgba(148,163,184,.35)}",
      ".zztt-head{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;align-items:flex-start}",
      ".zztt-title{font-size:19px;font-weight:800;letter-spacing:-.01em}",
      ".zztt-sub{font-size:12px;opacity:.65;margin-top:3px;max-width:640px}",
      ".zztt-head-right{display:flex;gap:10px;align-items:center}",
      ".zztt-chips{display:flex;gap:6px;background:rgba(148,163,184,.16);padding:4px;border-radius:10px}",
      ".zztt-chip{border:0;background:transparent;color:inherit;font:inherit;font-size:12px;font-weight:700;padding:7px 12px;border-radius:8px;cursor:pointer;opacity:.7}",
      ".zztt-chip[data-active='1']{background:var(--panel,#fff);opacity:1;box-shadow:0 1px 4px rgba(15,23,42,.18)}",
      ".zztt-close{border:1px solid rgba(148,163,184,.5);background:transparent;color:inherit;border-radius:9px;width:34px;height:34px;font-size:14px;cursor:pointer}",
      ".zztt-totals{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 10px}",
      ".zztt-pill{font-size:11.5px;font-weight:800;border:1.5px solid;border-radius:999px;padding:4px 10px}",
      ".zztt-scroll{overflow-x:auto;border:1px solid rgba(148,163,184,.35);border-radius:12px}",
      ".zztt-table{border-collapse:collapse;width:100%;min-width:900px;font-size:12px}",
      ".zztt-table th,.zztt-table td{border-bottom:1px solid rgba(148,163,184,.28);padding:8px 9px;vertical-align:top;text-align:left}",
      ".zztt-table thead th{background:rgba(148,163,184,.14);position:sticky;top:0}",
      ".zztt-day{display:block;font-size:12.5px;font-weight:800}",
      ".zztt-date{display:block;font-size:10.5px;font-weight:600;opacity:.6;margin-top:2px}",
      ".zztt-rowhead{width:186px;min-width:186px;background:rgba(148,163,184,.08)}",
      ".zztt-rowhead span{display:block}.zztt-rowhead em{font-style:normal;font-size:10.5px;opacity:.65;font-weight:600}",
      ".zztt-dot{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:6px}",
      ".zztt-cell{min-width:118px}",
      ".zztt-times{font-variant-numeric:tabular-nums;font-weight:700;line-height:1.45}",
      ".zztt-total{margin-top:4px;font-size:10.5px;font-weight:800;opacity:.6}",
      ".zztt-off{opacity:.28;text-align:center}",
      ".zztt-foot{font-size:11px;font-weight:800}.zztt-foot span{font-weight:600;opacity:.6}",
      ".zztt-foothead{font-size:11px;opacity:.7}",
      ".zztt-section{font-size:13px;font-weight:800;margin:20px 0 8px}",
      ".zztt-section span{font-weight:600;opacity:.6;font-size:11.5px}",
      ".zztt-compact th,.zztt-compact td{text-align:center;padding:7px 6px}",
      ".zztt-compact tbody th{text-align:left;width:120px;font-size:11.5px}",
      ".zztt-rank{font-weight:700;font-variant-numeric:tabular-nums}",
      ".zztt-best{color:#b45309;font-weight:900}",
      ".zztt-ok,.zztt-warn{margin-top:12px;font-size:11.5px;font-weight:700;border-radius:9px;padding:8px 11px}",
      ".zztt-ok{background:rgba(16,185,129,.12);color:#047857}",
      ".zztt-warn{background:rgba(245,158,11,.16);color:#b45309}",
      ".zztt-note{margin-top:10px;font-size:11px;opacity:.6}",
      ".zztt-empty{padding:18px;font-weight:700}",
      "@media(max-width:640px){.zztt-panel{padding:14px}.zztt-rowhead{width:132px;min-width:132px}}"
    ].join("\n");
    var style = document.createElement("style");
    style.id = "zztt-style";
    style.textContent = css;
    document.head.appendChild(style);
  }

  function panelHTML() {
    return '<div class="zztt-panel" role="dialog" aria-modal="true" aria-label="Study timetable"><div id="zztt-body"></div></div>';
  }

  function render() {
    var body = document.getElementById("zztt-body");
    if (!body) return;
    body.innerHTML = buildHTML(state.group);
    var close = document.getElementById("zztt-close");
    if (close) close.addEventListener("click", hide);
    Array.prototype.forEach.call(body.querySelectorAll(".zztt-chip"), function (chip) {
      chip.addEventListener("click", function () {
        state.group = chip.getAttribute("data-group");
        render();
      });
    });
  }

  function show() {
    injectStyle();
    var overlay = document.getElementById("zztt-overlay");
    if (!overlay) {
      overlay = document.createElement("div");
      overlay.id = "zztt-overlay";
      overlay.innerHTML = panelHTML();
      overlay.addEventListener("click", function (event) {
        if (event.target === overlay) hide();
      });
      document.body.appendChild(overlay);
    }
    overlay.setAttribute("data-open", "1");
    render();
    document.body.style.overflow = "hidden";
  }

  function hide() {
    var overlay = document.getElementById("zztt-overlay");
    if (overlay) overlay.setAttribute("data-open", "0");
    document.body.style.overflow = "";
  }

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") hide();
  });

  window.zzShowTimetable = show;
  window.zzBuildTimetableHTML = buildHTML;
})();
